-- Final schema expects PT409; historical-prefix runners explicitly set bracket.test_business_sqlstate.
begin;
select no_plan();
insert into templates(id,name,type) values('b2900000-0000-4000-8000-000000000001','SYNTHETIC integrity','bracket');
insert into leagues(id,name,template_id) values('b2900000-0000-4000-8000-000000000002','SYNTHETIC integrity','b2900000-0000-4000-8000-000000000001');
insert into participants(id,league_id,display_name,magic_token) values('b2900000-0000-4000-8000-000000000003','b2900000-0000-4000-8000-000000000002','Synthetic','b2900000-0000-4000-8000-000000000004');
insert into event_template_configs(template_id,version,sealed,manifest) values('b2900000-0000-4000-8000-000000000001',1,true,'{"markets":[{"id":"m1","windowId":"w1","choices":["a","b"]}]}');
insert into event_league_evaluations(league_id,configuration_version) values('b2900000-0000-4000-8000-000000000002',1);
insert into event_league_windows(league_id,window_key,state,cutoff,pairings_reviewed,market_ids) values('b2900000-0000-4000-8000-000000000002','w1','open',clock_timestamp()+interval '1 day',true,array['m1']);

insert into leagues(id,name,template_id) values('b2900000-0000-4000-8000-000000000005','SYNTHETIC revision','b2900000-0000-4000-8000-000000000001');
insert into event_league_evaluations(league_id,configuration_version) values('b2900000-0000-4000-8000-000000000005',1);
set local role service_role;
select lives_ok($$insert into event_template_configs(template_id,version,sealed,manifest) values('b2900000-0000-4000-8000-000000000001',2,true,'{"markets":[{"id":"m1","windowId":"w1","choices":["c","d"]}]}')$$,'immutable revision can be published separately');
select throws_ok($$update event_template_configs set sealed=false where template_id='b2900000-0000-4000-8000-000000000001' and version=1$$,'23514','sealed configuration is immutable','cannot unseal history');
select throws_ok($$delete from event_template_configs where template_id='b2900000-0000-4000-8000-000000000001' and version=1$$,'23514','sealed configuration is immutable','cannot delete history');
select throws_ok($$insert into event_template_configs(template_id,version,sealed,manifest) values('b2900000-0000-4000-8000-000000000001',3,true,'{"markets":[{"id":"m1","windowId":"w1","choices":["a","a"]}]}')$$,'23514','invalid window manifest','duplicate choices cannot publish');
select throws_ok($$insert into event_template_configs(template_id,version,sealed,manifest) values('b2900000-0000-4000-8000-000000000001',3,true,'{"markets":[{"id":"m1","windowId":"w1","choices":["a"]},{"id":"m1","windowId":"w2","choices":["b"]}]}')$$,'23514','invalid window manifest','duplicate logical identity cannot publish');
select lives_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','w1',0,'unopened',null,false,array['m1'])$$,'service creates reviewed logical window via ordered command');
select lives_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','w1',1,null,null,null,null,true)$$,'draft projection can be removed before seal');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000005'),3::bigint,'DELETE records obligation');
select lives_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','w1',0,'unopened',null,false,array['m1'])$$,'draft projection can be rebuilt');
select lives_ok($$select adopt_event_configuration('b2900000-0000-4000-8000-000000000005',1,2)$$,'pre-prediction revision adoption succeeds');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000005'),6::bigint,'revision and window version atomically generate work');
select is((select version from event_league_windows where league_id='b2900000-0000-4000-8000-000000000005'),3,'basis adoption invalidates prior window version');
select is((select configuration_version from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000002'),1,'unadopted league retains immutable v1');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000002'),2::bigint,'revision does not generate work for unaffected league');
select throws_ok($$select adopt_event_configuration('b2900000-0000-4000-8000-000000000005',1,1)$$,coalesce(nullif(current_setting('bracket.test_business_sqlstate',true),''),'PT409'),'configuration unavailable or stale','stale adoption rejected');
select ok(not has_table_privilege('service_role','event_league_windows','UPDATE'),'service direct window DML revoked');
select ok(not has_column_privilege('service_role','event_league_evaluations','configuration_version','UPDATE'),'service cannot bypass adoption ordering');
select ok(not has_table_privilege('service_role','event_template_configs','TRUNCATE'),'service cannot truncate immutable snapshots');
select ok(not has_function_privilege('anon','configure_event_window(uuid,text,integer,text,timestamptz,boolean,text[],boolean)','EXECUTE'),'anon cannot configure windows');
reset role;
set local role service_role;
select throws_ok($$update event_template_configs set manifest='{"markets":[{"id":"m1","windowId":"w1","choices":["c","d"]}]}' where template_id='b2900000-0000-4000-8000-000000000001' and version=1$$,'23514','sealed configuration is immutable','F2 same version mutation rejects');
select throws_ok($$select submit_event_window('b2900000-0000-4000-8000-000000000002','b2900000-0000-4000-8000-000000000004','w1',NULL,'{"m1":"a"}')$$,coalesce(nullif(current_setting('bracket.test_business_sqlstate',true),''),'PT409'),'window unavailable or stale','F4 NULL version rejects');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000002'),2::bigint,'rejections do not generate work');
select throws_ok($$select submit_event_window('b2900000-0000-4000-8000-000000000002','b2900000-0000-4000-8000-000000000004','w1',0,'{"m1":"a"}')$$,coalesce(nullif(current_setting('bracket.test_business_sqlstate',true),''),'PT409'),'window unavailable or stale','zero version rejects');
select lives_ok($$select submit_event_window('b2900000-0000-4000-8000-000000000002','b2900000-0000-4000-8000-000000000004','w1',1,'{"m1":"a"}')$$,'versioned complete submission succeeds');
select is((select membership_sealed from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000002'),true,'first successful prediction seals membership');
select throws_ok($$select adopt_event_configuration('b2900000-0000-4000-8000-000000000002',1,2)$$,'23514','sealed configuration basis cannot change','prediction history cannot be rebased');
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000002','w1',1,null,null,null,null,true)$$,'23514','sealed market membership cannot change','sealed before cutoff protects DELETE under service role');
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000002','extra',0,'unopened',null,false,array['extra'])$$,'23514','sealed market membership cannot change','sealed before cutoff protects INSERT under service role');
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000002','w1',1,'open',clock_timestamp()+interval '1 hour',true,array['renamed'])$$,'23514','sealed market membership cannot change','sealed before cutoff protects UPDATE under service role');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000002'),3::bigint,'all rejected sealed mutations are atomic');
reset role;
update event_league_windows set cutoff=clock_timestamp()-interval '1 second' where league_id='b2900000-0000-4000-8000-000000000002';
select throws_ok($$update event_league_windows set market_ids=array['renamed'] where league_id='b2900000-0000-4000-8000-000000000002'$$,'23514','sealed market membership cannot change','F3 semantic cutoff protects UPDATE before sweep');
select throws_ok($$insert into event_league_windows(league_id,window_key,market_ids) values('b2900000-0000-4000-8000-000000000002','late',array['extra'])$$,'23514','sealed market membership cannot change','F3 semantic cutoff protects INSERT');
select throws_ok($$delete from event_league_windows where league_id='b2900000-0000-4000-8000-000000000002'$$,'23514','sealed market membership cannot change','F3 semantic cutoff protects DELETE');
select is((select version from event_league_windows where league_id='b2900000-0000-4000-8000-000000000002'),2,'cutoff change increments optimistic version');
select is((select locked_at is null from leagues where id='b2900000-0000-4000-8000-000000000002'),true,'cutoff protection does not depend on sweep');
select throws_ok($$update event_league_windows set window_key='renamed' where league_id='b2900000-0000-4000-8000-000000000002'$$,'23514','window identity is immutable','window identity cannot be relabeled');
select is(advance_event_windows('b2900000-0000-4000-8000-000000000002'),1,'advance retains original mapping');
select is((select count(*) from picks where league_id='b2900000-0000-4000-8000-000000000002' and locked),1::bigint,'original pick is locked, not orphaned');
select throws_ok($$delete from event_league_windows where league_id='b2900000-0000-4000-8000-000000000002'$$,'23514','sealed market membership cannot change','physical lifecycle also prevents DELETE');
-- Independent semantic cutoff fixture: no picks, membership_sealed false, no sweep.
update event_league_windows set cutoff=clock_timestamp()-interval '1 second' where league_id='b2900000-0000-4000-8000-000000000005';
set local role service_role;
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','w1',4,null,null,null,null,true)$$,'23514','sealed market membership cannot change','semantic cutoff alone blocks service deletion');
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','extra',0,'unopened',null,false,array['extra'])$$,'23514','sealed market membership cannot change','semantic cutoff alone blocks service insertion');
select throws_ok($$select configure_event_window('b2900000-0000-4000-8000-000000000005','w1',4,'unopened',null,false,array['renamed'])$$,'23514','sealed market membership cannot change','semantic cutoff alone blocks service membership change');
reset role;
-- A partial projection cannot accept predictions even before any cutoff.
insert into templates(id,name,type) values('b2900000-0000-4000-8000-000000000010','SYNTHETIC incomplete','bracket');
insert into event_template_configs(template_id,version,sealed,manifest) values('b2900000-0000-4000-8000-000000000010',1,true,'{"markets":[{"id":"m1","windowId":"w1","choices":["a"]},{"id":"m2","windowId":"w2","choices":["b"]}]}');
insert into leagues(id,name,template_id) values('b2900000-0000-4000-8000-000000000011','SYNTHETIC incomplete','b2900000-0000-4000-8000-000000000010');
insert into event_league_evaluations(league_id,configuration_version) values('b2900000-0000-4000-8000-000000000011',1);
insert into participants(id,league_id,display_name,magic_token) values('b2900000-0000-4000-8000-000000000012','b2900000-0000-4000-8000-000000000011','Synthetic','b2900000-0000-4000-8000-000000000013');
set local role service_role;
select configure_event_window('b2900000-0000-4000-8000-000000000011','w1',0,'open',clock_timestamp()+interval '1 day',true,array['m1']);
select throws_ok($$select submit_event_window('b2900000-0000-4000-8000-000000000011','b2900000-0000-4000-8000-000000000013','w1',1,'{"m1":"a"}')$$,'23514','complete logical membership required','future slots must exist before any predictions');
select is((select generation from event_league_evaluations where league_id='b2900000-0000-4000-8000-000000000011'),2::bigint,'incomplete membership submission has no generation side effect');
select configure_event_window('b2900000-0000-4000-8000-000000000011','w2',0,'unopened',null,false,array['m2']);
select lives_ok($$select submit_event_window('b2900000-0000-4000-8000-000000000011','b2900000-0000-4000-8000-000000000013','w1',1,'{"m1":"a"}')$$,'complete future projection permits current submission');
reset role;
select throws_ok($$update leagues set template_id='b2900000-0000-4000-8000-000000000010' where id='b2900000-0000-4000-8000-000000000002'$$,'23514','event template association is immutable','template cannot reinterpret persisted configuration version');
select is((select count(*) from event_template_configs where template_id='b2900000-0000-4000-8000-000000000001'),2::bigint,'both immutable versions retained');
select * from finish();
rollback;
